#!/usr/bin/env python3
"""
Build Session Helper

Reads HEARTBEAT.md, picks exactly one concrete task to work on,
and writes a concise session log in Markdown.

Deterministic, handles missing files gracefully, and preserves
existing notes while appending new session entries.
"""

from datetime import datetime
from pathlib import Path
import hashlib
import re

HEARTBEAT_FILE = "HEARTBEAT.md"
NOTES_FILE = "project_notes.txt"
SESSION_LOG_FILE = "session_log.md"


def read_file(filepath):
    """Read file contents, return None if file doesn't exist."""
    path = Path(filepath)
    if not path.exists():
        return None
    return path.read_text(encoding="utf-8")


def write_file(filepath, content, append=False):
    """Write content to file. If append=True, append to existing content."""
    path = Path(filepath)
    if append and path.exists():
        with open(path, "a", encoding="utf-8") as f:
            f.write(content)
    else:
        path.write_text(content, encoding="utf-8")


def extract_tasks(content):
    """Extract task items from HEARTBEAT.md content."""
    if not content:
        return []
    tasks = []
    for line in content.splitlines():
        match = re.match(r"^\s*[-*]\s+(.+)$", line)
        if match:
            task = match.group(1).strip()
            if not task.startswith("MARKER") and task:
                tasks.append(task)
    return tasks


def pick_task_deterministic(tasks):
    """Pick exactly one task deterministically using hash-based selection."""
    if not tasks:
        return "No tasks available"
    seed = datetime.now().strftime("%Y%m%d") + ":" + ":".join(sorted(tasks))
    hash_val = int(hashlib.sha256(seed.encode()).hexdigest(), 16)
    index = hash_val % len(tasks)
    return tasks[index]


def generate_session_log(task):
    """Generate session log entry in Markdown format."""
    timestamp = datetime.now().strftime("%H:%M")
    log_entry = f"""## Build Session: {timestamp} - {task}

### What I Built
[Description of deliverable]

### Key Insights
[Anything learned worth remembering]

### Git
[Committed/pushed status]

"""
    return log_entry


def main():
    heartbeat_content = read_file(HEARTBEAT_FILE)
    if heartbeat_content is None:
        print(f"Warning: {HEARTBEAT_FILE} not found. Creating placeholder task.")
        task = "Initialize project setup"
    else:
        tasks = extract_tasks(heartbeat_content)
        if not tasks:
            print(f"Warning: No tasks found in {HEARTBEAT_FILE}")
            task = "Review project status"
        else:
            task = pick_task_deterministic(tasks)
    session_log = generate_session_log(task)
    write_file(SESSION_LOG_FILE, session_log, append=True)
    print(f"Selected task: {task}")
    print(f"Session log written to: {SESSION_LOG_FILE}")


if __name__ == "__main__":
    main()
ENDOFFILE
